class CarGallery{constructor(){this.slides=document.querySelectorAll(".slide"),this.loadedImages=new Set,this.init()}init(){this.loadActiveSlideImage(),this.setupLazyLoading(),this.addEventListeners()}addEventListeners(){const e=document.querySelector(".container");e.addEventListener("click",this.handleSlideClick.bind(this)),e.addEventListener("mouseenter",this.handleMouseEnter.bind(this),!0)}handleSlideClick(e){const t=e.target.closest(".slide");t&&requestAnimationFrame(()=>{this.clearActiveClasses(),t.classList.add("active"),this.loadSlideImage(t)})}handleMouseEnter(e){const t=e.target.closest(".slide");t&&!this.loadedImages.has(t)&&this.loadSlideImage(t)}clearActiveClasses(){this.slides.forEach(e=>{e.classList.remove("active")})}loadActiveSlideImage(){const e=document.querySelector(".slide.active");e&&this.loadSlideImage(e)}loadSlideImage(e){if(this.loadedImages.has(e))return;const t=e.dataset.bg;if(!t)return;e.classList.add("loading");const s=new Image;s.onload=()=>{e.style.backgroundImage=`url('${t}')`,e.classList.remove("loading"),this.loadedImages.add(e)},s.onerror=()=>{e.classList.remove("loading"),console.warn(`Failed to load image: ${t}`)},s.src=t}setupLazyLoading(){const e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(this.loadSlideImage(t.target),e.unobserve(t.target))})},{root:null,rootMargin:"50px",threshold:.1});this.slides.forEach(t=>{t.classList.contains("active")||e.observe(t)})}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>new CarGallery):new CarGallery;